        #[cfg(feature = "check-units")]
        {
        let u1 = v[1] * v[1];
        let u2 = v[0].mul_add(v[0], u1);
        let u3 = u2 - T::from_i64(1);
            T::check_unit(&[u3]);
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[1];
        let m2 = v[1] * v[1];
        let m3 = m0 - m2;
        let m4 = m1 * T::from_i64(2);
        let m5 = -m4;
        let m6 = m0 + m2;
